// @ts-check
// One generated page: Starlight frontmatter derived from the source file, then the source's body
// with its links rewritten (src/guides/markdown.mjs, src/guides/links.mjs).
import { siteUrlFor } from './links.mjs'
import { transformGuide } from './markdown.mjs'

/** The second line of every generated file; the sync deletes only files that start with it. */
export const generatedMarker = '# Generated by apps/site/src/guides/sync.mjs from'

/**
 * @typedef {object} PageContext
 * @property {import('./catalog.mjs').Page} page
 * @property {import('./catalog.mjs').Framework} framework
 * @property {string} siteTitle The site's title, for the page's `<title>`.
 * @property {string} base The site's base path, without a trailing slash.
 * @property {string} repository
 * @property {string} branch
 * @property {Date | undefined} lastUpdated When the source last changed (its last commit).
 * @property {import('./links.mjs').LinkContext['kindOf']} kindOf
 * @property {import('./links.mjs').LinkContext['routeOf']} routeOf
 */

/**
 * The generated Markdown file for a page.
 *
 * @param {string} source The source file's content.
 * @param {PageContext} context
 */
export function renderPage(source, context) {
  const { page, framework, base, repository, branch } = context
  /** @type {import('./links.mjs').LinkContext} */
  const links = {
    from: page.path,
    folder: framework.folder,
    base,
    repository,
    branch,
    kindOf: context.kindOf,
    routeOf: context.routeOf,
  }
  const guide = transformGuide(source, {
    name: page.source,
    rewrite: (target, kind) => siteUrlFor(target, links, { image: kind === 'image' }),
  })
  return `${frontmatter({
    title: guide.title,
    description: guide.description,
    framework: framework.id,
    editUrl: `${repository}/edit/${branch}/${page.source}`,
    lastUpdated: context.lastUpdated,
    label: page.label ?? guide.title,
    order: page.order,
    documentTitle: `${guide.title} (${framework.label}) | ${context.siteTitle}`,
    source: page.source,
  })}\n${guide.body}`
}

/**
 * Starlight frontmatter. String values are written as JSON, which is valid YAML, so quotes,
 * colons and backticks need no thought; the date is a bare YAML timestamp, which Astro reads as a
 * Date (Starlight's `lastUpdated` takes a Date, not a string).
 *
 * @param {object} data
 * @param {string} data.title
 * @param {string | undefined} data.description
 * @param {import('./catalog.mjs').FrameworkId} data.framework
 * @param {string} data.editUrl
 * @param {Date | undefined} data.lastUpdated
 * @param {string} data.label
 * @param {number} data.order
 * @param {string} data.documentTitle The `<title>`: React and Angular pages of the same guide
 *   share a title, so it names the framework.
 * @param {string} data.source
 */
export function frontmatter(data) {
  const string = JSON.stringify
  const lines = [
    '---',
    `${generatedMarker} ${data.source}: edit that file, not this one.`,
    `title: ${string(data.title)}`,
    ...(data.description ? [`description: ${string(data.description)}`] : []),
    `framework: ${string(data.framework)}`,
    `topic: ${string(data.framework)}`,
    `editUrl: ${string(data.editUrl)}`,
    ...(data.lastUpdated ? [`lastUpdated: ${data.lastUpdated.toISOString()}`] : []),
    'sidebar:',
    `  label: ${string(data.label)}`,
    `  order: ${data.order}`,
    'head:',
    '  - tag: title',
    `    content: ${string(data.documentTitle)}`,
    '---',
  ]
  return `${lines.join('\n')}\n`
}
